import { cx } from '@/lib/cx';
import './meter-list.css';

/**
 * B6 · MeterList — named items with 3px bars. The absolute-numbers
 * subtitle is REQUIRED: a percentage alone is a defect. Replaces every
 * donut/gauge (Firewall A2). Answers "how is each part doing."
 */
export interface MeterItem {
  label: string;
  current: number;
  max: number;
  /** Formatted value shown right, e.g. "92%". */
  value: string;
  /** REQUIRED absolute numbers, e.g. "4,320 of 4,700 pallet positions". */
  subtitle: string;
}

export interface MeterListProps {
  items: MeterItem[];
  className?: string;
}

export function MeterList({ items, className }: MeterListProps) {
  return (
    <div className={cx('sv-meters', className)}>
      {items.map((item) => (
        <div
          key={item.label}
          className="sv-meters__row"
          role="progressbar"
          aria-label={`${item.label}: ${item.subtitle}`}
          aria-valuenow={item.current}
          aria-valuemin={0}
          aria-valuemax={item.max}
        >
          <div className="sv-meters__line">
            <span className="sv-meters__label">{item.label}</span>
            <span className="sv-meters__value sv-num">{item.value}</span>
          </div>
          <div className="sv-meters__track">
            <div
              className="sv-meters__fill"
              style={{ width: `${item.max > 0 ? Math.min(100, (item.current / item.max) * 100) : 0}%` }}
            />
          </div>
          <p className="sv-meters__subtitle">{item.subtitle}</p>
        </div>
      ))}
    </div>
  );
}

/* B6 · MeterList */

@layer sv-components {
  .sv-meters {
    display: flex;
    flex-direction: column;
    gap: 13px;
  }

  .sv-meters__line {
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    margin-bottom: var(--sv-s1);
  }

  .sv-meters__label {
    font-size: 12.5px;
    font-weight: 500;
    color: var(--sv-ink-soft);
  }

  .sv-meters__value {
    font-size: 12.5px;
    font-weight: 700;
  }

  .sv-meters__track {
    height: 3px;
    border-radius: 2px;
    background: var(--sv-wall);
  }

  .sv-meters__fill {
    height: 100%;
    border-radius: 2px;
    background: var(--sv-seed);
    transition: width var(--sv-t);
  }

  .sv-meters__subtitle {
    margin-top: var(--sv-s1);
    font-size: 11px;
    color: var(--sv-ink-soft);
  }

  /* ---- v0.9 · the bars arrive, and they are OFF until the app asks ----

     B4's argument, verbatim, because B6 is B4's list form: a scaleX from
     the left rather than a width (A1 forbids animating layout, and the
     registered `width` exception is for a value CHANGE), the final frame
     is the element's ordinary state, and --sv-t-enter with base.css's
     ease-out-cubic rather than a tempo of its own.

     THE BARS DO NOT STAGGER, and that is the whole difference between a
     list arriving and a list performing. A queue of delayed children is
     the page putting on a show — use-reveal.ts refuses one by name for a
     page's sections and a MeterList is the same refusal at widget scale.
     Every fill starts on the same frame and lands on the same frame; the
     rows differ by the LENGTH they draw, which is the data, and that is
     already printed twice on every row (B6 requires the value right and
     the absolute-numbers subtitle under the track). Delete every
     declaration below and the list states each figure exactly as it did. */
  [data-motion='on'] .sv-meters__fill {
    transform-origin: left center;
    animation: sv-meters-grow var(--sv-t-enter) cubic-bezier(0.215, 0.61, 0.355, 1);
  }

  @keyframes sv-meters-grow {
    from {
      transform: scaleX(0);
    }
  }

  @media (prefers-reduced-motion: reduce) {
    [data-motion='on'] .sv-meters__fill {
      animation: none;
      transition: none;
    }
  }
}
